import numpy as np, pickle, os
rng=np.random.default_rng(1234)
pop=np.array([i.bit_count() for i in range(1<<14)],dtype=np.uint8)
ws={0}; witnesses={}
for core in range(7):
 masks=np.array([i | ((1<<core)-1) for i in range(1<<core,1<<14) if i.bit_count()==7 and i&((1<<core)-1)==0],dtype=np.uint16) if False else np.array([i for i in range(1<<14) if i.bit_count()==7 and i&((1<<core)-1)==((1<<core)-1)],dtype=np.uint16)
 for k in range(2,9):
  for it in range(5):
   a=rng.choice(masks,size=(k,20000)); unions=np.zeros((1<<k,20000),dtype=np.uint16); w=np.zeros(20000,dtype=np.int32)
   for s in range(1,1<<k):
    j=(s&-s).bit_length()-1
    unions[s]=unions[s^(1<<j)] | a[j]
    w+=(-2)**(s.bit_count()-1)* (1<<(14-pop[unions[s]].astype(np.int32)))
   vals,ix=np.unique(w,return_index=True)
   for v,i in zip(vals,ix):
    if v<=500:
     ws.add(int(v)); witnesses[int(v)]=a[:,i].tolist()
 print(core,sorted(ws))
pickle.dump((ws,witnesses),open('sample.pkl','wb'))

