import numpy as np,pickle,itertools
rng=np.random.default_rng(4123);m=13;r=7
pop=np.array([i.bit_count() for i in range(1<<m)],dtype=np.uint8); masks=np.where(pop==r)[0].astype(np.uint16)
found={}; pol=[]
for k in range(3,10):
 for it in range(30):
  a=rng.choice(masks,size=(k,20000)); unions=np.zeros((1<<k,20000),dtype=np.uint16); w=np.zeros(20000,dtype=np.int32)
  for s in range(1,1<<k):
   j=(s&-s).bit_length()-1
   unions[s]=unions[s^(1<<j)]|a[j]
   w+=(-2)**(s.bit_count()-1)*(1<<(m-pop[unions[s]].astype(np.int32)))
  for i in np.where(w==160)[0][:20]:pol.append(a[:,i].tolist())
print('polys',len(pol),flush=True)
subsets=list(itertools.combinations(range(m),6)); inds=np.empty((len(subsets),64,128),dtype=np.uint16)
for i,S in enumerate(subsets):
 T=[j for j in range(m) if j not in S]
 a=np.array([sum(((k>>t)&1)<<s for t,s in enumerate(S)) for k in range(64)],dtype=np.uint16)
 b=np.array([sum(((k>>t)&1)<<s for t,s in enumerate(T)) for k in range(128)],dtype=np.uint16)
 inds[i]=a[:,None]|b[None,:]
X=np.arange(1<<m,dtype=np.uint16)
for idx,p in enumerate(pol):
 f=np.zeros(1<<m,dtype=np.uint8)
 for a in p:f^=((X&a)==a)
 counts=f[inds].sum(axis=2)
 if (counts==63).any():
  q,z=np.argwhere(counts==63)[0];mask=sum(1<<s for s in subsets[q]); b=int(inds[q,z,0]);
  print('FOUND322',p,mask,b,flush=True)
  pickle.dump((p,mask,b),open('w322.pkl','wb'));break
 if idx%100==0:print(idx,flush=True)
else:print('not found')

