from math import comb,prod
import itertools,z3,pickle,time
out={}
for groups in [(4,5,5),(2,6,6),(3,5,6),(3,4,7),(2,2,5,5),(1,1,6,6),(3,3,4,4),(2,3,4,5)]:
 pts=list(itertools.product(*(range(g+1) for g in groups)));mult=[prod(comb(g,k) for g,k in zip(groups,p)) for p in pts]
 ys=[z3.Bool('y%d'%i) for i in range(len(pts))]
 s=z3.Solver();s.set(timeout=60000)
 for i,p in enumerate(pts):
  if sum(p)>7:
   inds=[j for j,q in enumerate(pts) if all(b & ~a==0 for a,b in zip(p,q))]
   s.add(z3.Not(z3.Xor(*[ys[j] for j in inds])) if len(inds)>1 else z3.Not(ys[inds[0]]))
 for i,w in enumerate(mult):
  if w>334:s.add(z3.Not(ys[i]))
 print(groups,len(pts),flush=True)
 for t in [322,326,330,334]:
  if t in out:continue
  s.push();s.add(z3.PbEq(list(zip(ys,mult)),t));ans=s.check();print(t,ans,flush=True)
  if ans==z3.sat:
   M=s.model();support=[p for p,y in zip(pts,ys) if z3.is_true(M[y])]
   mons=[p for p in pts if sum(1 for q in support if all(b & ~a==0 for a,b in zip(p,q)))%2]
   out[t]=(groups,mons);print(out[t],flush=True);pickle.dump(out,open('z3words.pkl','wb'))
  s.pop()
 if len(out)==4:break

