from sage.all import Matrix,GF
B,w,reps,d=pickle.load(open('pairinv7.pkl','rb'));active=np.where(B.any(axis=0))[0];B=B[:,active];w=w[active];reps=reps[active]
C=Matrix(GF(2),B.tolist()).right_kernel().basis_matrix();ys=[z3.Bool('y%d'%i) for i in range(len(w))]
s=z3.Solver();s.set(timeout=300000)
for row in C:
 q=[ys[i] for i,b in enumerate(row) if b]
 if q:s.add(z3.Not(functools.reduce(z3.Xor,q)))
for target in [322,326,330]:
 s.push();s.add(z3.PbEq([(y,int(v)) for y,v in zip(ys,w)],target));r=s.check();print(target,r,flush=True)
 if r==z3.sat:
  vals=np.array([z3.is_true(s.model()[y]) for y in ys]);print('support',reps[vals],w[vals],flush=True);pickle.dump((reps,vals),open('pairword%d.pkl'%target,'wb'))
 s.pop()

