import numpy as np,pickle,z3,functools
from sage.all import Matrix,GF
# permutations GL(3,2) on seven nonzero vectors, duplicated on 2 copies
p1=[((i<<1)&7)|(i>>2) for i in range(1,8)]
p2=[i^(((i>>1)&1)<<0) for i in range(1,8)]
perms=[[i-1 for i in p1]+[i+6 for i in p1],[i-1 for i in p2]+[i+6 for i in p2],list(range(7,14))+list(range(7))]
for swap in [True,False]:
 maps=[]
 for perm in perms[:3 if swap else 2]:
  maps.append(np.array([sum(((x>>j)&1)<<perm[j] for j in range(14)) for x in range(16384)],dtype=np.uint16))
 seen=set();orbs=[]
 for x in range(16384):
  if x in seen:continue
  orb={x};todo=[x]
  while todo:
   a=todo.pop()
   for M in maps:
    b=int(M[a])
    if b not in orb:orb.add(b);todo.append(b)
  seen.update(orb);orbs.append(sorted(orb))
 reps=np.array([o[0] for o in orbs],dtype=np.uint16);w=np.array(list(map(len,orbs)),dtype=np.int64)
 mons=[o for o in orbs if o[0].bit_count()<=7];rows=[]
 for o in mons:
  row=np.zeros(len(reps),dtype=np.uint8)
  for a in o:row^=((reps&a)==a)
  rows.append(row.tolist())
 G=Matrix(GF(2),rows);forbid=[i for i,v in enumerate(w) if v>334]
 K=G.matrix_from_columns(forbid).transpose().right_kernel().basis_matrix();B=K*G
 C=B.right_kernel().basis_matrix();ys=[z3.Bool('y%d'%i) for i in range(len(w))]
 print('swap',swap,'n',len(w),'k',B.nrows(),flush=True)
 s=z3.Solver();s.set(timeout=120000)
 for row in C:
  q=[ys[i] for i,b in enumerate(row) if b]
  if q:s.add(z3.Not(functools.reduce(z3.Xor,q)))
 for target in [322,326,330,334]:
  s.push();s.add(z3.PbEq([(y,int(v)) for y,v in zip(ys,w)],target));r=s.check();print(target,r,flush=True)
  if r==z3.sat:
   vals=np.array([z3.is_true(s.model()[y]) for y in ys]);print('support',reps[vals],w[vals],flush=True);pickle.dump((orbs,vals),open('glword%d.pkl'%target,'wb'))
  s.pop()

