import numpy as np,pickle,itertools,time
from sage.all import Matrix,GF
B,w,orbs=pickle.load(open('glinv.pkl','rb'));B=Matrix(GF(2),B.tolist());heavy=[i for i,v in enumerate(w) if v>=42];light=[i for i,v in enumerate(w) if v<42];nh=len(heavy)
Q=B.matrix_from_columns(heavy).right_kernel().basis_matrix();synd=[sum(int(Q[j,i])<<j for j in range(Q.nrows())) for i in range(nh)]
one=[i for i,x in enumerate(heavy) if w[x]==42];two=[i for i,x in enumerate(heavy) if w[x]==84];four=[i for i,x in enumerate(heavy) if w[x]==168]
print('synd rank',Q.nrows(), 'sizes',len(one),len(two),len(four),flush=True)
small=[(0,0,0)]
def addsub(inds,cost,out):
 for I in inds:
  mask=sum(1<<i for i in I);s=0
  for i in I:s^=synd[i]
  out.append((s,mask,cost))
addsub(((i,) for i in one),1,small);addsub(((i,) for i in two),2,small);addsub(itertools.combinations(one,2),2,small);addsub(itertools.product(one,two),3,small);addsub(itertools.combinations(one,3),3,small)
large=small.copy();addsub(((i,) for i in four),4,large);addsub(itertools.combinations(two,2),4,large);addsub((a+(b,) for a in itertools.combinations(one,2) for b in two),4,large);addsub(itertools.combinations(one,4),4,large)
dictsmall={}
for s,mask,c in small:dictsmall.setdefault(s,[]).append((mask,c))
valid={0:0}
for s,m,c in large:
 for mm,cc in dictsmall.get(s,[]):
  if m&mm==0 and c+cc<=7:valid[m|mm]=(c+cc)*42
print('valid heavy',len(valid),flush=True)
# Includes configs total8 units? targets max334 =>atmost7 yes. Everycost7 partition3+4? e.g4+2+1 yes; 2+2+2+1=>3+4; correct.
E=B.matrix_from_columns(heavy+light).echelon_form(); piv=E.pivots();rankh=sum(p<nh for p in piv);diml=E.nrows()-rankh
print(rankh,diml,flush=True)
Eb=np.array(E.list(),dtype=np.uint8).reshape(E.nrows(),len(w)); L=Eb[rankh:,nh:]; nums=np.arange(1<<diml,dtype=np.uint64);coeff=((nums[:,None] & np.array([1<<i for i in range(diml)],dtype=np.uint64))!=0).astype(np.uint8);LW=(coeff@L)%2
wl=w[light];out={}
start=time.time()
for it,(mask,hw) in enumerate(valid.items()):
 c=np.array([(mask>>p)&1 for p in piv[:rankh]],dtype=np.uint8);off=(c@Eb[:rankh,nh:])%2
 vals=LW^off;weights=vals@wl+hw
 for target in [322,326,330,334]:
  if target in out:continue
  inds=np.where(weights==target)[0]
  if len(inds):
   vv=np.zeros(len(w),dtype=np.uint8);vv[light]=vals[inds[0]];vv[heavy]=[(mask>>j)&1 for j in range(nh)]
   out[target]=vv;print('FOUND',target,it,flush=True);pickle.dump((orbs,out),open('glfound.pkl','wb'))
 if it%100==0:print(it,time.time()-start,flush=True)
 if len(out)==4:break
print('out',list(out),flush=True)

